
#!/usr/bin/env bash
set -euo pipefail

# ------------------------------------------------------------
# Module I - Transcript assembly with PsiCLASS
#
# Input:  Six coordinate-sorted BAM files generated by STAR
# Output: Per-sample and unified transcript assemblies (GTF)
#
# Reference: Johns Hopkins University RNA-seq course
# ------------------------------------------------------------

# Project directories
BASEDIR="/mnt/d/Bioinformatics/transcriptomics-data/Module_I"
ALNDIR="${BASEDIR}/results/STAR"
WORKDIR="${BASEDIR}/results/PsiClass"

# Sample metadata
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="$(dirname "$SCRIPT_DIR")"
RUN_LIST="${PROJECT_DIR}/metadata/selected_runs.txt"

# Output files
BAM_LIST="${WORKDIR}/bamlist.psiclass"
OUTPUT_PREFIX="${WORKDIR}/psiclass"
LOG_FILE="${WORKDIR}/psiclass.log"

# Number of PsiCLASS processes
THREADS=2

# ------------------------------------------------------------
# 1. Check required software and files
# ------------------------------------------------------------

command -v psiclass >/dev/null 2>&1 || {
    echo "ERROR: PsiCLASS is not available in the current environment." >&2
    exit 1
}

command -v samtools >/dev/null 2>&1 || {
    echo "ERROR: SAMtools is not available in the current environment." >&2
    exit 1
}

if [[ ! -f "$RUN_LIST" ]]; then
    echo "ERROR: Sample list not found: $RUN_LIST" >&2
    exit 1
fi

mkdir -p "$WORKDIR"

# ------------------------------------------------------------
# 2. Create BAM list
# ------------------------------------------------------------

# Create the list in a temporary file first.
# The final list is replaced only after all BAMs pass validation.

BAM_LIST_TMP="$(mktemp "${WORKDIR}/bamlist.XXXXXX")"
trap 'rm -f "$BAM_LIST_TMP"' EXIT

SAMPLE_COUNT=0

while IFS= read -r run || [[ -n "$run" ]]; do

    # Skip blank lines and comments
    [[ -z "$run" || "$run" == \#* ]] && continue

    BAM="${ALNDIR}/${run}_Aligned.sortedByCoord.out.bam"

    echo "Checking sample: $run"

    if [[ ! -s "$BAM" ]]; then
        echo "ERROR: Missing or empty BAM: $BAM" >&2
        exit 1
    fi

    if ! samtools quickcheck -v "$BAM"; then
        echo "ERROR: BAM failed validation: $BAM" >&2
        exit 1
    fi

    printf '%s\n' "$BAM" >> "$BAM_LIST_TMP"
    SAMPLE_COUNT=$((SAMPLE_COUNT + 1))

done < "$RUN_LIST"

if [[ "$SAMPLE_COUNT" -ne 6 ]]; then
    echo "ERROR: Expected 6 samples, found $SAMPLE_COUNT." >&2
    exit 1
fi

mv "$BAM_LIST_TMP" "$BAM_LIST"

echo "BAM list created successfully."
echo "Number of samples: $SAMPLE_COUNT"
cat "$BAM_LIST"

# ------------------------------------------------------------
# 3. Run PsiCLASS
# ------------------------------------------------------------

echo "Starting PsiCLASS transcript assembly..."
echo "Output directory: $WORKDIR"
echo "Processes: $THREADS"

psiclass \
    --lb "$BAM_LIST" \
    -o "$OUTPUT_PREFIX" \
    -p "$THREADS" \
    > "$LOG_FILE" 2>&1

echo "PsiCLASS transcript assembly completed!"
echo "Log file: $LOG_FILE"
echo "Results directory: $WORKDIR"